command:
set -euo pipefail; git fetch origin --prune --quiet; test "$(git rev-parse HEAD)" = "$(git rev-parse origin/main)"; python3 - <<'PY'
import base64, hashlib, json, math, re, subprocess, tomllib, zlib
from pathlib import Path
ROOT=Path.cwd(); P=ROOT/'projects/kobra2-neo'
manifest=json.loads((P/'samples/gcode/shaft-120x20-technical-demo.job.json').read_text())
profile=tomllib.loads((P/'config/kobra2_neo_pen.toml').read_text())
vm=manifest['validated_machine_job']
assert profile['workspace']=={'min_x':3.0,'max_x':223.0,'min_y':36.0,'max_y':230.0,'margin':5.0}
assert profile['tool']=={'pen_up_z':6.12,'pen_down_z':2.97}
assert profile['motion']=={'travel_feed':3000.0,'draw_feed':1200.0,'z_feed':180.0}
assert vm['bounds_mm']=={'min_x':38.0,'max_x':191.68,'min_y':58.0,'max_y':208.0}
assert vm['polylines']==361 and vm['points']==5020
print('CALIBRATION_MANIFEST_OK', flush=True)
subprocess.run(['git','fetch','origin','agent-control'],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
old=json.loads(subprocess.check_output(['git','show','origin/agent-control:.agent/tasks/kobra2-neo-record-next-live-job-20260928-13.json'],text=True))
m=re.search(r"zlib\.decompress\(base64\.b64decode\('([^']+)'\)\)",old['commands'][0])
if not m: raise SystemExit('saved generator not found')
blob=m.group(1); source=None
for pad in range(5):
    try:
        source=zlib.decompress(base64.b64decode(blob+'='*pad)).decode(); break
    except Exception: pass
if source is None: raise SystemExit('saved generator cannot be recovered')
print('GENERATOR_SHA256='+hashlib.sha256(source.encode()).hexdigest(), flush=True)
exec(compile(source,'<saved-shaft-generator>','exec'),{'__name__':'__main__'})
gp=P/'samples/gcode/shaft-120x20-technical-demo.gcode'; rp=P/'samples/gcode/shaft-120x20-technical-demo.report.json'
if not gp.exists() or not rp.exists(): raise SystemExit('expected generated artifacts missing')
g=gp.read_text(); report=json.loads(rp.read_text())
assert report['safety']['valid'] is True
assert report['profile']['pen_up_z']==6.12 and report['profile']['pen_down_z']==2.97
assert report['bounds_mm']==vm['bounds_mm']
active=[]; bounds=[1e99,-1e99,1e99,-1e99]; points=downs=0
for n,line in enumerate(g.splitlines(),1):
    s=line.split(';',1)[0].strip()
    if not s: continue
    p=s.split(); cmd=p[0].upper()
    if cmd not in {'G90','G0','G1','M400'}: raise SystemExit(f'forbidden command line {n}: {cmd}')
    vals={}
    for tok in p[1:]:
        mm=re.fullmatch(r'([A-Za-z])([-+]?\d+(?:\.\d+)?)',tok)
        if not mm: raise SystemExit(f'malformed token line {n}: {tok}')
        vals[mm.group(1).upper()]=float(mm.group(2))
    if 'E' in vals: raise SystemExit(f'extrusion line {n}')
    if cmd in {'G90','M400'}:
        if vals: raise SystemExit(f'params on {cmd} line {n}')
    elif 'Z' in vals:
        if cmd!='G0' or set(vals)!={'Z','F'} or vals['Z'] not in {6.12,2.97} or vals['F']!=180.0: raise SystemExit(f'bad Z line {n}')
        downs += vals['Z']==2.97
    else:
        if set(vals)!={'X','Y','F'}: raise SystemExit(f'bad XY line {n}')
        x,y=vals['X'],vals['Y']
        if not (8<=x<=218 and 41<=y<=225): raise SystemExit(f'XY out of bounds line {n}: {x},{y}')
        if cmd=='G0' and vals['F']!=3000.0: raise SystemExit(f'bad travel feed line {n}')
        if cmd=='G1' and vals['F']!=1200.0: raise SystemExit(f'bad draw feed line {n}')
        bounds=[min(bounds[0],x),max(bounds[1],x),min(bounds[2],y),max(bounds[3],y)]; points+=1
    active.append(s)
if active[0].upper()!='G90' or active[-1].upper()!='M400': raise SystemExit('bad first/last artwork command')
expected=[38.0,191.68,58.0,208.0]
if any(not math.isclose(a,b,abs_tol=1e-6) for a,b in zip(bounds,expected)): raise SystemExit(f'bounds mismatch {bounds}')
if points!=5020 or downs!=361: raise SystemExit(f'geometry counts mismatch points={points} polylines={downs}')
if re.search(r'(^|\s)G28(?:\s|$)',g,re.I|re.M): raise SystemExit('G28 found in artwork')
for bad in ('M104','M109','M140','M190'):
    if bad in g.upper(): raise SystemExit(f'heater command found: {bad}')
print(f'PREFLIGHT_ARTWORK_OK bounds=X[{bounds[0]:.2f},{bounds[1]:.2f}] Y[{bounds[2]:.2f},{bounds[3]:.2f}] polylines={downs} points={points} commands={len(active)} sha256={hashlib.sha256(g.encode()).hexdigest()}', flush=True)
PY
